1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { Page } from './page';
4	import { Plugin, PluginContext } from './plugin';
5	
6	export interface EngineOptions {
7	  contentDir: string;
8	  outputDir: string;
9	  templatesDir: string;
10	  plugins: Plugin[];
11	  config?: Record<string, unknown>;
12	}
13	
14	function findMarkdownFiles(dir: string): string[] {
15	  if (!fs.existsSync(dir)) {
16	    throw new Error(`Content directory not found: ${dir}`);
17	  }
18	
19	  const results: string[] = [];
20	  const entries = fs.readdirSync(dir, { withFileTypes: true });
21	
22	  for (const entry of entries) {
23	    const fullPath = path.join(dir, entry.name);
24	    if (entry.isDirectory()) {
25	      results.push(...findMarkdownFiles(fullPath));
26	    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
27	      results.push(fullPath);
28	    }
29	  }
30	
31	  return results.sort();
32	}
33	
34	function slugFromPath(contentDir: string, filePath: string): string {
35	  const relative = path.relative(contentDir, filePath);
36	  const withoutExt = relative.replace(/\.md$/i, '');
37	  return withoutExt.split(path.sep).join('/');
38	}
39	
40	function stubPage(contentDir: string, filePath: string): Page {
41	  const slug = slugFromPath(contentDir, filePath);
42	  return {
43	    slug,
44	    title: '',
45	    date: null,
46	    tags: [],
47	    html: '',
48	    sourcePath: filePath,
49	    outputPath: `${slug}.html`,
50	    template: '',
51	    layout: '',
52	  };
53	}
54	
55	/**
56	 * Orchestrates the plugin pipeline: discovers content files and runs every
57	 * registered plugin's hooks in registration order. Plugins own everything
58	 * about how a file becomes output (parsing, rendering, writing) - the
59	 * engine only owns discovery and hook sequencing.
60	 */
61	export class SSGEngine {
62	  readonly ctx: PluginContext;
63	
64	  private readonly plugins: Plugin[];
65	
66	  constructor(options: EngineOptions) {
67	    this.ctx = {
68	      contentDir: options.contentDir,
69	      outputDir: options.outputDir,
70	      templatesDir: options.templatesDir,
71	      config: options.config ?? {},
72	    };
73	    this.plugins = options.plugins;
74	  }
75	
76	  start(): void {
77	    for (const plugin of this.plugins) {
78	      plugin.onStart?.(this.ctx);
79	    }
80	  }
81	
82	  end(): void {
83	    for (const plugin of this.plugins) {
84	      plugin.onEnd?.(this.ctx);
85	    }
86	  }
87	
88	  build(): Page[] {
89	    for (const plugin of this.plugins) {
90	      plugin.beforeBuild?.(this.ctx);
91	    }
92	
93	    const files = findMarkdownFiles(this.ctx.contentDir);
94	    const pages: Page[] = [];
95	
96	    for (const file of files) {
97	      let page = stubPage(this.ctx.contentDir, file);
98	      for (const plugin of this.plugins) {
99	        const result = plugin.onFile?.(page, this.ctx);
100	        if (result) page = result;
101	      }
102	      pages.push(page);
103	    }
104	
105	    for (const plugin of this.plugins) {
106	      plugin.afterBuild?.(pages, this.ctx);
107	    }
108	
109	    return pages;
110	  }
111	
112	  /** Runs a full onStart -> build -> onEnd pass and returns the built pages. */
113	  run(): Page[] {
114	    this.start();
115	    const pages = this.build();
116	    this.end();
117	    return pages;
118	  }
119	}
