1	import { Page } from './page';
2	
3	export interface PluginContext {
4	  contentDir: string;
5	  outputDir: string;
6	  templatesDir: string;
7	  config: Record<string, unknown>;
8	}
9	
10	/**
11	 * A build-pipeline extension point. Every hook is optional and synchronous:
12	 * the whole pipeline (and `buildSite`) is intentionally sync so the public
13	 * API stays a plain function call, not a Promise.
14	 *
15	 * Hook order for a single build pass: onStart, beforeBuild, onFile (once per
16	 * discovered content file, in file order), afterBuild, onEnd.
17	 */
18	export interface Plugin {
19	  name: string;
20	  onStart?(ctx: PluginContext): void;
21	  beforeBuild?(ctx: PluginContext): void;
22	  onFile?(page: Page, ctx: PluginContext): Page | void;
23	  afterBuild?(pages: Page[], ctx: PluginContext): void;
24	  onEnd?(ctx: PluginContext): void;
25	}
