7	export interface BuildOptions {
8	  contentDir: string;
9	  outputDir: string;
10	  templatesDir?: string;
11	  /** Overrides the plugin pipeline instead of loading it from ssg.config.ts. */
12	  plugins?: Plugin[];
13	  /** Path to a config file to load plugins from; defaults to ssg.config.ts. */
14	  configPath?: string;
15	}
