22	export function buildSite(options: BuildOptions): BuildResult {
23	  const contentDir = path.resolve(options.contentDir);
24	  const outputDir = path.resolve(options.outputDir);
25	  const templatesDir = path.resolve(options.templatesDir ?? './templates');
26	
27	  const plugins = options.plugins ?? loadConfig(options.configPath).plugins;
28	
29	  const engine = new SSGEngine({ contentDir, outputDir, templatesDir, plugins });
30	  const pages = engine.run();
31	
32	  return { pages, outputDir };
33	}
