1	import * as path from 'path';
2	import { Plugin } from './plugin';
3	import { markdownPlugin } from '../plugins/markdown-plugin';
4	import { templatePlugin } from '../plugins/template-plugin';
5	
6	export interface SSGConfig {
7	  plugins: Plugin[];
8	}
9	
10	function builtInDefaultPlugins(): Plugin[] {
11	  return [markdownPlugin(), templatePlugin()];
12	}
13	
14	function defaultConfigPath(): string {
15	  return path.resolve(__dirname, '..', 'ssg.config');
16	}
17	
18	/**
19	 * Loads the plugin pipeline from `ssg.config.ts` (or a custom path). Falls
20	 * back to the built-in markdown + template plugins whenever no config file
21	 * is present, or the file exists but doesn't export a usable plugin list -
22	 * this keeps `buildSite`/`startDevServer` working with zero configuration.
23	 */
24	export function loadConfig(configPath?: string): SSGConfig {
25	  const resolvedPath = configPath ? path.resolve(configPath) : defaultConfigPath();
26	
27	  try {
28	    // eslint-disable-next-line @typescript-eslint/no-var-requires
29	    const mod = require(resolvedPath);
30	    const config = (mod?.default ?? mod) as Partial<SSGConfig> | undefined;
31	    if (config && Array.isArray(config.plugins) && config.plugins.length > 0) {
32	      return { plugins: config.plugins };
33	    }
34	  } catch {
35	    // No config file at this path, or it failed to load - use the built-ins.
36	  }
37	
38	  return { plugins: builtInDefaultPlugins() };
39	}
