1	import * as fs from 'fs';
2	import { parseMarkdownFile } from '../src/frontmatter';
3	import { renderMarkdown } from '../src/markdown';
4	import { Page } from '../src/page';
5	import { Plugin } from '../src/plugin';
6	import { DEFAULT_LAYOUT_NAME, DEFAULT_TEMPLATE_NAME } from '../src/templates';
7	
8	function titleFromSlug(slug: string): string {
9	  const base = slug.split('/').pop() || slug;
10	  return base
11	    .replace(/[-_]+/g, ' ')
12	    .replace(/\b\w/g, (char) => char.toUpperCase());
13	}
14	
15	/**
16	 * Built-in plugin that turns a raw `.md` file into a fully populated Page:
17	 * splits frontmatter from body, renders the body to HTML, and resolves
18	 * title/date/tags/template/layout (falling back to sensible defaults).
19	 */
20	export function markdownPlugin(): Plugin {
21	  return {
22	    name: 'markdown',
23	    onFile(page: Page): Page {
24	      const raw = fs.readFileSync(page.sourcePath, 'utf-8');
25	      const { data, content } = parseMarkdownFile(raw);
26	      const html = renderMarkdown(content);
27	
28	      const title = typeof data.title === 'string' && data.title.trim() ? data.title : titleFromSlug(page.slug);
29	      const date = typeof data.date === 'string' && data.date.trim() ? data.date : null;
30	      const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];
31	      const template =
32	        typeof data.template === 'string' && data.template.trim() ? data.template : DEFAULT_TEMPLATE_NAME;
33	      const layout = typeof data.layout === 'string' && data.layout.trim() ? data.layout : DEFAULT_LAYOUT_NAME;
34	
35	      return { ...page, title, date, tags, html, template, layout };
36	    },
37	  };
38	}
