1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { Page } from '../src/page';
4	import { Plugin, PluginContext } from '../src/plugin';
5	import { DEFAULT_LAYOUT_NAME, INDEX_TEMPLATE_NAME, TemplateEngine } from '../src/templates';
6	
7	/**
8	 * Built-in plugin that renders each Page through the Handlebars template
9	 * engine and writes it to disk, then renders and writes the site index once
10	 * all pages are built.
11	 */
12	export function templatePlugin(): Plugin {
13	  let engine: TemplateEngine;
14	
15	  return {
16	    name: 'template',
17	    beforeBuild(ctx: PluginContext): void {
18	      engine = new TemplateEngine(ctx.templatesDir);
19	      fs.mkdirSync(ctx.outputDir, { recursive: true });
20	    },
21	    onFile(page: Page, ctx: PluginContext): void {
22	      const destPath = path.join(ctx.outputDir, page.outputPath);
23	      fs.mkdirSync(path.dirname(destPath), { recursive: true });
24	      const html = engine.render(page.template, page.layout, { ...page });
25	      fs.writeFileSync(destPath, html, 'utf-8');
26	    },
27	    afterBuild(pages: Page[], ctx: PluginContext): void {
28	      const indexPath = path.join(ctx.outputDir, 'index.html');
29	      const indexHtml = engine.render(INDEX_TEMPLATE_NAME, DEFAULT_LAYOUT_NAME, { title: 'Index', pages });
30	      fs.writeFileSync(indexPath, indexHtml, 'utf-8');
31	    },
32	  };
33	}
