1	import * as fs from 'fs';
2	import * as http from 'http';
3	import * as path from 'path';
4	import { WebSocket, WebSocketServer } from 'ws';
5	import { Page } from '../src/page';
6	import { Plugin } from '../src/plugin';
7	
8	export const LIVERELOAD_PATH = '/__livereload';
9	
10	const MIME_TYPES: Record<string, string> = {
11	  '.html': 'text/html; charset=utf-8',
12	  '.css': 'text/css; charset=utf-8',
13	  '.js': 'text/javascript; charset=utf-8',
14	  '.json': 'application/json; charset=utf-8',
15	  '.svg': 'image/svg+xml',
16	  '.png': 'image/png',
17	  '.jpg': 'image/jpeg',
18	  '.jpeg': 'image/jpeg',
19	  '.gif': 'image/gif',
20	  '.ico': 'image/x-icon',
21	  '.txt': 'text/plain; charset=utf-8',
22	};
23	
24	function liveReloadScript(): string {
25	  return `
26	<script>
27	(function () {
28	  var socket = new WebSocket('ws://' + window.location.host + '${LIVERELOAD_PATH}');
29	  socket.addEventListener('message', function (event) {
30	    if (event.data === 'reload') {
31	      window.location.reload();
32	    }
33	  });
34	})();
35	</script>
36	`;
37	}
38	
39	export function injectLiveReload(html: string): string {
40	  const script = liveReloadScript();
41	  if (html.includes('</body>')) {
42	    return html.replace('</body>', `${script}</body>`);
43	  }
44	  return `${html}${script}`;
45	}
46	
47	function resolveFilePath(outputDir: string, urlPath: string): string {
48	  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
49	  const relative = decoded.replace(/^\/+/, '') || 'index.html';
50	
51	  let filePath = path.join(outputDir, relative);
52	
53	  if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
54	    filePath = path.join(filePath, 'index.html');
55	  } else if (!fs.existsSync(filePath) && !path.extname(filePath)) {
56	    filePath = `${filePath}.html`;
57	  }
58	
59	  return filePath;
60	}
61	
62	function serveFile(outputDir: string, req: http.IncomingMessage, res: http.ServerResponse): void {
63	  const resolvedRoot = path.resolve(outputDir);
64	  const filePath = resolveFilePath(resolvedRoot, req.url ?? '/');
65	  const resolved = path.resolve(filePath);
66	
67	  const isWithinRoot = resolved === resolvedRoot || resolved.startsWith(resolvedRoot + path.sep);
68	  if (!isWithinRoot || !fs.existsSync(resolved) || fs.statSync(resolved).isDirectory()) {
69	    res.statusCode = 404;
70	    res.end('Not found');
71	    return;
72	  }
73	
74	  const ext = path.extname(resolved).toLowerCase();
75	  const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';
76	
77	  if (ext === '.html') {
78	    const html = fs.readFileSync(resolved, 'utf-8');
79	    res.setHeader('Content-Type', contentType);
80	    res.end(injectLiveReload(html));
81	    return;
82	  }
83	
84	  res.setHeader('Content-Type', contentType);
85	  fs.createReadStream(resolved).pipe(res);
86	}
87	
88	/**
89	 * Built-in plugin that serves the built output over HTTP with a live-reload
90	 * script injected into every HTML response, and broadcasts a reload message
91	 * to connected clients at the end of every build it takes part in. Starting
92	 * and stopping the HTTP/WebSocket server are explicit calls (`listen`,
93	 * `close`) rather than lifecycle hooks, since they bracket the whole dev
94	 * session rather than a single build pass.
95	 */
96	export class DevServerPlugin implements Plugin {
97	  readonly name = 'dev-server';
98	
99	  private readonly outputDir: string;
100	
101	  private httpServer: http.Server | null = null;
102	
103	  private wss: WebSocketServer | null = null;
104	
105	  constructor(outputDir: string) {
106	    this.outputDir = outputDir;
107	  }
108	
109	  afterBuild(_pages: Page[]): void {
110	    if (!this.wss) return;
111	    this.wss.clients.forEach((client) => {
112	      if (client.readyState === WebSocket.OPEN) {
113	        client.send('reload');
114	      }
115	    });
116	  }
117	
118	  listen(port: number): Promise<{ url: string; port: number }> {
119	    this.httpServer = http.createServer((req, res) => serveFile(this.outputDir, req, res));
120	    this.wss = new WebSocketServer({ server: this.httpServer, path: LIVERELOAD_PATH });
121	
122	    return new Promise((resolve, reject) => {
123	      const server = this.httpServer as http.Server;
124	      server.once('error', reject);
125	      server.listen(port, () => {
126	        const address = server.address();
127	        const actualPort = typeof address === 'object' && address ? address.port : port;
128	        resolve({ url: `http://localhost:${actualPort}`, port: actualPort });
129	      });
130	    });
131	  }
132	
133	  close(): Promise<void> {
134	    return new Promise((resolveClose) => {
135	      const wss = this.wss;
136	      const httpServer = this.httpServer;
137	      this.wss = null;
138	      this.httpServer = null;
139	
140	      if (!wss || !httpServer) {
141	        resolveClose();
142	        return;
143	      }
144	
145	      wss.close(() => {
146	        httpServer.close(() => resolveClose());
147	      });
148	    });
149	  }
150	}
