1	import { SSGConfig } from './src/config';
2	import { markdownPlugin } from './plugins/markdown-plugin';
3	import { templatePlugin } from './plugins/template-plugin';
4	
5	/**
6	 * Default plugin pipeline for this SSG. The dev server plugin is not listed
7	 * here - `startDevServer` appends it on top of this pipeline itself, since
8	 * it only applies to `ssg serve`, never to a plain `ssg build`.
9	 */
10	const config: SSGConfig = {
11	  plugins: [markdownPlugin(), templatePlugin()],
12	};
13	
14	export default config;
