1	import * as path from 'path';
2	import chokidar from 'chokidar';
3	import { DevServerPlugin, injectLiveReload, LIVERELOAD_PATH } from '../plugins/dev-server-plugin';
4	import { loadConfig } from './config';
5	import { buildSite, BuildOptions } from './site';
6	
7	export { injectLiveReload, LIVERELOAD_PATH };
8	
9	export interface ServeOptions extends BuildOptions {
10	  port?: number;
11	}
12	
13	export interface DevServer {
14	  url: string;
15	  port: number;
16	  close: () => Promise<void>;
17	}
18	
19	const REBUILD_DEBOUNCE_MS = 50;
20	
21	export function startDevServer(options: ServeOptions): Promise<DevServer> {
22	  const contentDir = path.resolve(options.contentDir);
23	  const outputDir = path.resolve(options.outputDir);
24	  const templatesDir = path.resolve(options.templatesDir ?? './templates');
25	  const requestedPort = options.port ?? 3000;
26	
27	  const basePlugins = options.plugins ?? loadConfig(options.configPath).plugins;
28	  const devServerPlugin = new DevServerPlugin(outputDir);
29	  const plugins = [...basePlugins, devServerPlugin];
30	
31	  const rebuild = (): void => {
32	    buildSite({ contentDir, outputDir, templatesDir, plugins });
33	  };
34	
35	  rebuild();
36	
37	  const listening = devServerPlugin.listen(requestedPort);
38	
39	  let rebuildTimer: ReturnType<typeof setTimeout> | null = null;
40	  const scheduleRebuild = (): void => {
41	    if (rebuildTimer) clearTimeout(rebuildTimer);
42	    rebuildTimer = setTimeout(() => {
43	      rebuildTimer = null;
44	      try {
45	        rebuild();
46	      } catch (err) {
47	        // eslint-disable-next-line no-console
48	        console.error('Rebuild failed:', err instanceof Error ? err.message : err);
49	      }
50	    }, REBUILD_DEBOUNCE_MS);
51	  };
52	
53	  const watcher = chokidar.watch([contentDir, templatesDir], { ignoreInitial: true });
54	  watcher.on('all', scheduleRebuild);
55	
56	  const watcherReady = new Promise<void>((resolveReady) => watcher.once('ready', () => resolveReady()));
57	
58	  return Promise.all([listening, watcherReady]).then(([{ port: actualPort }]) => ({
59	    url: `http://localhost:${actualPort}`,
60	    port: actualPort,
61	    close: () =>
62	      new Promise<void>((resolveClose) => {
63	        if (rebuildTimer) clearTimeout(rebuildTimer);
64	        watcher.close().then(() => {
65	          devServerPlugin.close().then(() => resolveClose());
66	        });
67	      }),
68	  }));
69	}
