import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import { Page } from './page';

export const DEFAULT_CACHE_FILENAME = '.ssg-cache.json';

const CACHE_VERSION = 1;

export interface CacheEntry {
  sourceHash: string;
  outputPath: string;
  page: Page;
  buildTimeMs: number;
}

interface CacheManifest {
  version: number;
  templatesHash: string;
  entries: Record<string, CacheEntry>;
}

export function hashContent(content: string): string {
  return crypto.createHash('sha1').update(content).digest('hex');
}

export function hashFile(filePath: string): string {
  return hashContent(fs.readFileSync(filePath, 'utf-8'));
}

/**
 * Hashes every `.hbs` file under `templatesDir` into one combined digest.
 * Deliberately coarse: a page's exact template/layout/partial chain is only
 * known after the markdown plugin's `onFile` hook runs (frontmatter can
 * override either), so per-page template dependencies can't be resolved
 * ahead of time without teaching the cache about plugin internals. Hashing
 * the whole directory means any template edit invalidates every cached page
 * rather than risking a stale render.
 */
export function hashTemplatesDir(templatesDir: string): string {
  const files: string[] = [];

  const walk = (dir: string): void => {
    if (!fs.existsSync(dir)) return;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (/\.hbs$/i.test(entry.name)) {
        files.push(fullPath);
      }
    }
  };
  walk(templatesDir);
  files.sort();

  const combined = files
    .map((file) => `${path.relative(templatesDir, file)}:${fs.readFileSync(file, 'utf-8')}`)
    .join('�');
  return hashContent(combined);
}

function readManifest(cachePath: string): CacheManifest | null {
  if (!fs.existsSync(cachePath)) return null;
  try {
    const parsed = JSON.parse(fs.readFileSync(cachePath, 'utf-8')) as Partial<CacheManifest>;
    if (parsed.version !== CACHE_VERSION || typeof parsed.entries !== 'object' || !parsed.entries) {
      return null;
    }
    return { version: CACHE_VERSION, templatesHash: parsed.templatesHash ?? '', entries: parsed.entries };
  } catch {
    return null;
  }
}

/**
 * Manifest-backed cache of per-page build results, keyed by absolute source
 * file path. `SSGEngine` uses this in `--incremental` mode to skip
 * re-running the plugin pipeline (and the disk write that goes with it) for
 * pages whose source content and templates are unchanged since the last
 * build. A cache is scrapped wholesale - starting from an empty entry set -
 * whenever the manifest is missing/unreadable, was written under a
 * different template set, or `clean` is requested.
 */
export class PageCache {
  private readonly templatesHash: string;

  private entries: Record<string, CacheEntry>;

  constructor(private readonly cachePath: string, templatesDir: string, clean: boolean) {
    this.templatesHash = hashTemplatesDir(templatesDir);
    const manifest = clean ? null : readManifest(cachePath);
    this.entries = manifest && manifest.templatesHash === this.templatesHash ? manifest.entries : {};
  }

  get(sourcePath: string): CacheEntry | undefined {
    return this.entries[sourcePath];
  }

  set(sourcePath: string, entry: CacheEntry): void {
    this.entries[sourcePath] = entry;
  }

  /** Drops entries for source files that no longer exist, so deleted pages don't linger in the manifest. */
  prune(liveSourcePaths: Set<string>): void {
    for (const key of Object.keys(this.entries)) {
      if (!liveSourcePaths.has(key)) delete this.entries[key];
    }
  }

  save(): void {
    const manifest: CacheManifest = {
      version: CACHE_VERSION,
      templatesHash: this.templatesHash,
